@* Displays a single task card with move buttons *@

<div class="task-card">
    <h4>@Task.Title</h4>
    <p class="assignee">@Task.Assignee</p>
    <span class="priority-badge priority-@Task.Priority.ToLowerInvariant()">@Task.Priority</span>
    <span class="due-date">@Task.DueDate.ToString("MMM dd")</span>

    <div class="task-actions">
        @if (CanMoveLeft)
        {
            <button class="btn-move" @onclick="OnMoveLeftClicked">← Move Left</button>
        }
        @if (CanMoveRight)
        {
            <button class="btn-move" @onclick="OnMoveRightClicked">Move Right →</button>
        }
    </div>
</div>

@code {
    [Parameter, EditorRequired]
    public TaskItem Task { get; set; } = default!;

    [Parameter]
    public bool CanMoveLeft { get; set; }

    [Parameter]
    public bool CanMoveRight { get; set; }

    [Parameter]
    public EventCallback OnMoveLeft { get; set; }

    [Parameter]
    public EventCallback OnMoveRight { get; set; }

    private async System.Threading.Tasks.Task OnMoveLeftClicked() => await OnMoveLeft.InvokeAsync();
    private async System.Threading.Tasks.Task OnMoveRightClicked() => await OnMoveRight.InvokeAsync();
}

@* Inline form for creating a new task within a column *@

<div class="add-task-form">
    <input type="text" @bind="title" placeholder="Title" />
    <input type="text" @bind="assignee" placeholder="Assignee" />
    <select @bind="priority">
        <option value="High">High</option>
        <option value="Medium">Medium</option>
        <option value="Low">Low</option>
    </select>
    <input type="date" @bind="dueDate" />

    <div class="form-actions">
        <button class="btn-save" @onclick="Save">Save</button>
        <button class="btn-cancel" @onclick="Cancel">Cancel</button>
    </div>
</div>

@code {
    [Parameter, EditorRequired]
    public string DefaultStatus { get; set; } = default!;

    [Parameter]
    public EventCallback<(string Title, string Assignee, string Priority, DateTime DueDate)> OnSave { get; set; }

    [Parameter]
    public EventCallback OnCancel { get; set; }

    private string title = string.Empty;
    private string assignee = string.Empty;
    private string priority = "Medium";
    private DateTime dueDate = DateTime.Today.AddDays(7);

    private async Task Save()
    {
        if (!string.IsNullOrWhiteSpace(title))
        {
            await OnSave.InvokeAsync((title, assignee, priority, dueDate));
            title = string.Empty;
            assignee = string.Empty;
            priority = "Medium";
            dueDate = DateTime.Today.AddDays(7);
        }
    }

    private async Task Cancel() => await OnCancel.InvokeAsync();
}

@* A single Kanban column with header, task cards, and add-task form *@

<div class="kanban-column">
    <div class="column-header">
        <h3>@ColumnName (@Tasks.Count)</h3>
    </div>

    <div class="column-body">
        @foreach (var task in Tasks)
        {
            <TaskCard Task="task"
                      CanMoveLeft="CanMoveLeft"
                      CanMoveRight="CanMoveRight"
                      OnMoveLeft="@(() => OnMoveTask.InvokeAsync((task.Id, MoveDirection.Left)))"
                      OnMoveRight="@(() => OnMoveTask.InvokeAsync((task.Id, MoveDirection.Right)))" />
        }
    </div>

    @if (showForm)
    {
        <AddTaskForm DefaultStatus="@ColumnName"
                     OnSave="HandleSave"
                     OnCancel="@(() => showForm = false)" />
    }
    else
    {
        <button class="btn-add-task" @onclick="@(() => showForm = true)">+ Add Task</button>
    }
</div>

@code {
    [Parameter, EditorRequired]
    public string ColumnName { get; set; } = default!;

    [Parameter, EditorRequired]
    public List<TaskItem> Tasks { get; set; } = new();

    [Parameter]
    public bool CanMoveLeft { get; set; }

    [Parameter]
    public bool CanMoveRight { get; set; }

    [Parameter]
    public EventCallback<(int TaskId, MoveDirection Direction)> OnMoveTask { get; set; }

    [Parameter]
    public EventCallback<(string Title, string Assignee, string Priority, DateTime DueDate)> OnAddTask { get; set; }

    private bool showForm;

    private async Task HandleSave((string Title, string Assignee, string Priority, DateTime DueDate) data)
    {
        await OnAddTask.InvokeAsync(data);
        showForm = false;
    }

    public enum MoveDirection { Left, Right }
}

@* Summary stats bar showing task counts *@

<div class="board-stats">
    <span class="stat">Total: <strong>@Total</strong></span>
    <span class="stat">To Do: <strong>@ToDo</strong></span>
    <span class="stat">In Progress: <strong>@InProgress</strong></span>
    <span class="stat">Done: <strong>@DoneCount</strong></span>
    <span class="stat overdue">Overdue: <strong>@Overdue</strong></span>
</div>

@code {
    [Parameter] public int Total { get; set; }
    [Parameter] public int ToDo { get; set; }
    [Parameter] public int InProgress { get; set; }
    [Parameter] public int DoneCount { get; set; }
    [Parameter] public int Overdue { get; set; }
}

